/* ============================================
   GreenBean Coffee — Design System
   ============================================ */

@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=Playfair+Display:wght@500;600;700&display=swap');

:root {
  /* Brand Colors */
  --green-primary: #00824A;
  --green-dark: #006B3D;
  --green-light: #E6F5ED;
  --forest: #32462F;
  --forest-light: #4A6345;
  --cream: #F3CEA1;
  --cream-light: #FDF6EC;
  --coffee: #6F4E37;
  --coffee-dark: #4A3428;
  --coffee-light: #C4A882;

  /* Neutral */
  --white: #FFFFFF;
  --gray-50: #FAFAF9;
  --gray-100: #F5F5F4;
  --gray-200: #E7E5E4;
  --gray-300: #D6D3D1;
  --gray-400: #A8A29E;
  --gray-500: #78716C;
  --gray-600: #57534E;
  --gray-700: #44403C;
  --gray-800: #292524;
  --gray-900: #1C1917;

  /* Semantic */
  --background: var(--white);
  --foreground: var(--gray-900);
  --primary: var(--green-primary);
  --primary-foreground: var(--white);
  --secondary: var(--cream-light);
  --secondary-foreground: var(--forest);
  --muted: var(--gray-100);
  --muted-foreground: var(--gray-500);
  --accent: var(--cream);
  --border: var(--gray-200);
  --ring: var(--green-primary);

  /* Typography */
  --font-sans: 'DM Sans', system-ui, -apple-system, sans-serif;
  --font-display: 'Playfair Display', Georgia, serif;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Radius */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.07), 0 2px 4px -2px rgb(0 0 0 / 0.05);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.07), 0 4px 6px -4px rgb(0 0 0 / 0.05);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.07), 0 8px 10px -6px rgb(0 0 0 / 0.05);
  --shadow-green: 0 4px 14px 0 rgba(0, 130, 74, 0.25);

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 350ms ease;
}

/* ============================================
   Base Styles
   ============================================ */

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--foreground);
  background-color: var(--background);
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: 600;
  line-height: 1.2;
  color: var(--forest);
}

a {
  color: var(--green-primary);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--green-dark);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font-family: var(--font-sans);
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ============================================
   Utility Classes
   ============================================ */

.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding-left: var(--space-4);
  padding-right: var(--space-4);
}

@media (min-width: 768px) {
  .container {
    padding-left: var(--space-6);
    padding-right: var(--space-6);
  }
}

@media (min-width: 1024px) {
  .container {
    padding-left: var(--space-8);
    padding-right: var(--space-8);
  }
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ============================================
   Header & Navigation
   ============================================ */

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
}

.logo {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--forest);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--green-primary);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
}

.main-nav {
  display: none;
}

@media (min-width: 768px) {
  .main-nav {
    display: flex;
    align-items: center;
    gap: var(--space-8);
  }
}

.nav-link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-700);
  padding: var(--space-2) 0;
  position: relative;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--green-primary);
  transition: width var(--transition-base);
}

.nav-link:hover,
.nav-link.active {
  color: var(--green-primary);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: 0.625rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background: var(--green-primary);
  color: var(--white);
  box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
  background: var(--green-dark);
  color: var(--white);
  box-shadow: var(--shadow-green);
  transform: translateY(-1px);
}

.btn-secondary {
  background: transparent;
  color: var(--forest);
  border: 1.5px solid var(--forest);
}

.btn-secondary:hover {
  background: var(--forest);
  color: var(--white);
}

.btn-ghost {
  background: transparent;
  color: var(--gray-700);
  padding: var(--space-2);
}

.btn-ghost:hover {
  color: var(--green-primary);
  background: var(--green-light);
}

.btn-sm {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

.btn-lg {
  padding: 0.875rem 2rem;
  font-size: 1rem;
}

.mobile-menu-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  color: var(--gray-700);
}

@media (min-width: 768px) {
  .mobile-menu-btn {
    display: none;
  }
}

.mobile-nav {
  display: none;
  position: absolute;
  top: 64px;
  left: 0;
  right: 0;
  background: var(--white);
  border-bottom: 1px solid var(--border);
  padding: var(--space-4);
  box-shadow: var(--shadow-lg);
}

.mobile-nav.open {
  display: block;
}

.mobile-nav a {
  display: block;
  padding: var(--space-3) 0;
  font-size: 1rem;
  font-weight: 500;
  color: var(--gray-700);
  border-bottom: 1px solid var(--gray-100);
}

.mobile-nav a:hover {
  color: var(--green-primary);
}

/* ============================================
   Hero Section
   ============================================ */

.hero {
  position: relative;
  min-height: 520px;
  display: flex;
  align-items: center;
  overflow: hidden;
  background: linear-gradient(135deg, var(--green-primary) 0%, var(--forest) 100%);
}

.hero-pattern {
  position: absolute;
  inset: 0;
  opacity: 0.08;
  background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='1'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 600px;
}

.hero-title {
  font-size: clamp(2.25rem, 5vw, 3.5rem);
  font-weight: 700;
  color: var(--white);
  margin-bottom: var(--space-6);
  line-height: 1.1;
}

.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: rgba(255, 255, 255, 0.85);
  margin-bottom: var(--space-8);
  line-height: 1.6;
}

.hero-cta {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 1rem 2rem;
  background: var(--white);
  color: var(--green-primary);
  font-size: 1rem;
  font-weight: 700;
  border-radius: var(--radius-full);
  box-shadow: var(--shadow-lg);
  transition: all var(--transition-fast);
}

.hero-cta:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-xl);
  color: var(--green-dark);
}

.hero-image {
  position: absolute;
  right: 0;
  top: 0;
  bottom: 0;
  width: 50%;
  opacity: 0.25;
  object-fit: cover;
}

@media (min-width: 1024px) {
  .hero-image {
    opacity: 0.9;
    width: 45%;
  }
}

/* ============================================
   Section Styles
   ============================================ */

.section {
  padding: var(--space-16) 0;
}

.section-alt {
  background: var(--gray-50);
}

.section-cream {
  background: var(--cream-light);
}

.section-green {
  background: var(--green-primary);
  color: var(--white);
}

.section-green h2,
.section-green h3 {
  color: var(--white);
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto var(--space-12);
}

.section-title {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  margin-bottom: var(--space-4);
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--gray-500);
  line-height: 1.7;
}

/* ============================================
   Cards
   ============================================ */

.card {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--transition-base);
  border: 1px solid var(--border);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.card-image {
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
}

.card-body {
  padding: var(--space-6);
}

.card-title {
  font-size: 1.25rem;
  margin-bottom: var(--space-2);
}

.card-text {
  color: var(--gray-500);
  font-size: 0.9375rem;
  line-height: 1.6;
  margin-bottom: var(--space-4);
}

/* ============================================
   Promo / Feature Sections
   ============================================ */

.promo-section {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-8);
  align-items: center;
}

@media (min-width: 768px) {
  .promo-section {
    grid-template-columns: 1fr 1fr;
    gap: var(--space-12);
  }
}

.promo-section.reverse {
  direction: rtl;
}

.promo-section.reverse > * {
  direction: ltr;
}

.promo-image {
  border-radius: var(--radius-2xl);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}

.promo-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  aspect-ratio: 4 / 3;
}

.promo-label {
  display: inline-block;
  padding: var(--space-1) var(--space-3);
  background: var(--green-light);
  color: var(--green-primary);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-full);
  margin-bottom: var(--space-3);
}

.promo-title {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  margin-bottom: var(--space-4);
}

.promo-text {
  font-size: 1.0625rem;
  color: var(--gray-500);
  line-height: 1.7;
  margin-bottom: var(--space-6);
}

/* ============================================
   Grid Layouts
   ============================================ */

.grid-2 {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
}

.grid-3 {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
}

.grid-4 {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-6);
}

@media (min-width: 640px) {
  .grid-2 { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 768px) {
  .grid-3 { grid-template-columns: repeat(3, 1fr); }
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
}

@media (min-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(4, 1fr); }
}

/* ============================================
   Rewards Tabs
   ============================================ */

.tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-bottom: var(--space-8);
  justify-content: center;
}

.tab-btn {
  padding: var(--space-3) var(--space-5);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--gray-600);
  background: var(--white);
  border: 2px solid var(--border);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.tab-btn:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

.tab-btn.active {
  background: var(--green-primary);
  color: var(--white);
  border-color: var(--green-primary);
  box-shadow: var(--shadow-green);
}

.tab-panel {
  display: none;
  animation: fadeIn 350ms ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ============================================
   Rewards Tier Cards
   ============================================ */

.tier-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: var(--space-8);
  border: 2px solid var(--border);
  transition: all var(--transition-base);
  position: relative;
  overflow: hidden;
}

.tier-card:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.tier-card.featured {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-green);
}

.tier-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: var(--space-4);
  right: var(--space-4);
  padding: var(--space-1) var(--space-3);
  background: var(--green-primary);
  color: var(--white);
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-radius: var(--radius-full);
}

.tier-name {
  font-size: 1.5rem;
  margin-bottom: var(--space-2);
}

.tier-stars {
  font-size: 1rem;
  color: var(--green-primary);
  font-weight: 600;
  margin-bottom: var(--space-4);
}

.tier-benefits {
  list-style: none;
}

.tier-benefits li {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  padding: var(--space-2) 0;
  font-size: 0.9375rem;
  color: var(--gray-600);
}

.tier-benefits li i {
  color: var(--green-primary);
  flex-shrink: 0;
  margin-top: 2px;
}

/* ============================================
   Gift Card Carousel
   ============================================ */

.carousel-wrapper {
  position: relative;
}

.carousel {
  display: flex;
  gap: var(--space-4);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: var(--space-2) 0;
}

.carousel::-webkit-scrollbar {
  display: none;
}

.carousel-item {
  flex: 0 0 auto;
  scroll-snap-align: start;
  width: 260px;
}

.gift-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
  transition: all var(--transition-base);
}

.gift-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.gift-card-image {
  width: 100%;
  aspect-ratio: 1.6 / 1;
  object-fit: cover;
}

.gift-card-body {
  padding: var(--space-4);
}

.gift-card-title {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--forest);
}

.carousel-nav {
  display: flex;
  gap: var(--space-2);
  margin-top: var(--space-4);
  justify-content: flex-end;
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-full);
  background: var(--white);
  border: 1.5px solid var(--border);
  color: var(--gray-600);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--green-primary);
  border-color: var(--green-primary);
  color: var(--white);
}

.carousel-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ============================================
   Store Locator
   ============================================ */

.locator-bar {
  background: var(--white);
  border-bottom: 1px solid var(--border);
  padding: var(--space-4) 0;
}

.locator-controls {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
  align-items: center;
}

.toggle-group {
  display: inline-flex;
  background: var(--gray-100);
  border-radius: var(--radius-full);
  padding: 4px;
}

.toggle-btn {
  padding: var(--space-2) var(--space-4);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-600);
  border-radius: var(--radius-full);
  transition: all var(--transition-fast);
}

.toggle-btn.active {
  background: var(--white);
  color: var(--green-primary);
  box-shadow: var(--shadow-sm);
}

.search-input-wrapper {
  position: relative;
  flex: 1;
  min-width: 260px;
}

.search-input {
  width: 100%;
  padding: 0.625rem 1rem 0.625rem 2.75rem;
  font-size: 0.9375rem;
  border: 1.5px solid var(--border);
  border-radius: var(--radius-full);
  background: var(--white);
  transition: all var(--transition-fast);
}

.search-input:focus {
  outline: none;
  border-color: var(--green-primary);
  box-shadow: 0 0 0 3px rgba(0, 130, 74, 0.1);
}

.search-input-wrapper i {
  position: absolute;
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-400);
}

.filter-btn {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  padding: 0.625rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--forest);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-full);
  background: var(--white);
  transition: all var(--transition-fast);
}

.filter-btn:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
}

.filter-panel {
  display: none;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  margin-top: var(--space-4);
  box-shadow: var(--shadow-lg);
}

.filter-panel.open {
  display: block;
  animation: fadeIn 250ms ease;
}

.filter-options {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-3);
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 0.9375rem;
  color: var(--gray-700);
  cursor: pointer;
}

.filter-option input {
  width: 18px;
  height: 18px;
  accent-color: var(--green-primary);
}

.suggestions {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
